class AsiMgr(UnixFunctionality):
    """
    Class with robot keywords for the AsiMgr device.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self, device_name='GNB0_ASIMGR', pw="Nemuadmin:nemuuser", ne="192.168.255.129",
                 autoconnect=False, get_device=False):
        """
        Setting default parameters.
        """
        super(AsiMgr, self).__init__(device_name=device_name, autoconnect=autoconnect, get_device=get_device)

        self.pw = pw
        self.ne = ne

    @MolerTest.raise_background_exceptions(check_steps_end=True)
    def connect_to_asimgr(self):
        """
        The keyword creates the AsiMgr device object based on the given device name.

        :return: nothing
        """
        self.connect()

        MolerTest.steps_end()

    @MolerTest.raise_background_exceptions()
    def convert_xml_to_dict(self, path_to_file, force_list=None):
        """
        Takes xml file and parse it into dictionary.

        :param path_to_file: path to xml file
        :param force_list: tuple of keys. If the key for a given level of hierarchy is in the force_list argument,
        that level of hierarchy will have a list as a child.
        :return: Dictionary of parsed xml.
        """

        file_content = self.get_file_content(path_to_file)

        file_content = "\n".join(file_content)

        dict_output = xmltodict.parse(file_content, force_list=force_list)

        return dict_output

    def _get_ant_partial_info(self, instance, ele):
        """
        used to get specific ant mo particular info and store them into list.

        :return      dict
        """
        antfields = {}
        if instance.hasAttribute("class") and instance.getAttribute("class") == "com.nokia.asi:{0}".format(ele):
            antfields["@id"] = instance.getAttribute("distName").split("/")[-1].split("-")[1]
            name_list = ["productCode", "serialNumber", "antPortRDN", "configDN"]
            antdata = instance.getElementsByTagName("p")
            for d in antdata:
                if d.getAttribute("name") in name_list:
                    antfields[d.getAttribute("name")] = d.childNodes[0].data
            return antfields

    @MolerTest.raise_background_exceptions()
    def get_ant_hwinfo(self, file, hubruntime_name):
        """
        Get hw information of ASI ants using WEBEM.

        :return        list of dicts, each dict contains information about Ant_R object
        :rtype         list
        """
        antinfo = []
        antHwInfo = []
        domTree = parse(file)
        rootNode = domTree.documentElement
        Mo = rootNode.getElementsByTagName("managedObject")
        for mo in Mo:
            return_result = self._get_ant_partial_info(mo, 'ANTMOD_R')
            if return_result:
                antinfo.append(return_result)

        for ant_Hwinfo in antinfo:
            if hubruntime_name == ant_Hwinfo["antPortRDN"].split("/")[-2]:
                ant_Hwinfo["antPortRDN"] = ant_Hwinfo["antPortRDN"].split("-")[-1]
                ant_Hwinfo["configDN"] = ant_Hwinfo["configDN"].split("-")[-1]
                antHwInfo.append(ant_Hwinfo)
        return antHwInfo

    def _get_hub_partial_info(self, instance, ele):
        """
        used to get specific hub mo particular info and store them into list.

        :return      dict
        """
        hubfields = {}
        if instance.hasAttribute("class") and instance.getAttribute("class") == "com.nokia.asi:{0}".format(ele):
            hubfields["distName"] = instance.getAttribute("distName").split("/")[-1]
            name_list = ["configDN", "asiRmodId", "serialNumber", "productCode"]
            hubdata = instance.getElementsByTagName("p")
            for d in hubdata:
                if d.hasAttribute("name") and d.getAttribute("name") in name_list:
                    hubfields[d.getAttribute("name")] = d.childNodes[0].data
            return hubfields

    def _get_hub_hw_subinfo(self, hub_info, hw_info, hub_num):
        """
        used to get hub specific hw info

        :return      str
        """
        try:
            for hubid in hub_info:
                if hubid["distName"].split("-")[-1] == hub_num:
                    runtime_name = hubid["distName"]
                    hw_info["@id"] = hubid["configDN"].split("-")[-1]
                    hw_info["serialNumber"] = hubid["serialNumber"]
                    hw_info["productCode"] = hubid["productCode"]
                    hw_info["asiRmodId"] = hubid["asiRmodId"]
                    return runtime_name

        except Exception as e:
            logging.info("Exception when calling _get_hubhw_subinfo: %s\n" % e)

    @MolerTest.raise_background_exceptions()
    def get_hub_hwinfo(self, file=None, hubnum=None):
        """
        Get hw information of ASI Hubs and ASI ants using WEBEM.

        :return        list of dicts, each dict contains information about Hub_R or Ant_R object
        :rtype         list
        """
        hubinfo = []
        hubHwInfo = {}
        anthwinfo = []
        domTree = parse(file)
        rootNode = domTree.documentElement
        Mo = rootNode.getElementsByTagName("managedObject")
        for mo in Mo:
            return_result = self._get_hub_partial_info(mo, 'HUBMOD_R')
            if return_result:
                hubinfo.append(return_result)

        hub_runtime_name = self._get_hub_hw_subinfo(hubinfo, hubHwInfo, hubnum)
        logging.info("Hub runtime name and it's HW info is : {0}/{1}".format(hub_runtime_name, hubHwInfo))

        anthwinfo = self.get_ant_hwinfo(file, hub_runtime_name)
        hubHwInfo["ANTMOD_R"] = anthwinfo
        return hubHwInfo

    @MolerTest.raise_background_exceptions()
    def asirmg_cli_get_asi_hw_data(self):
        """
        Executes GetHwInventoryInfo on Asir Manager and parses output file into dictionary.

        :return: Dictionary with GetHwInventoryInfo file output.
        """
        self.device.goto_state("CLI")

        cmd_get_hw_inventory_info = self.device.get_cmd(
            cmd_name="get_hw_inventory_info",
            cmd_params={"ne": self.ne, "pw": self.pw})
        cmd_get_hw_inventory_info(timeout=150)

        filename = "GetHwInventInfo_{}.xml".format(self.ne)

        hw_inventory_info = self.convert_xml_to_dict(filename, force_list=('HUBMOD_R', 'ANTMOD_R'))

        return hw_inventory_info

    @MolerTest.raise_background_exceptions()
    def get_asi_hw_data_based_on_commissioning(self, outputdir='/tmp', path_to_scf=None):
        """
        Get HW information of ASI Hubs and ASI Ants using WEBEM.

        :return                  list of dicts, each dict contains information about Hub_R or Ant_R object
        :rtype                   list
        """
        if path_to_scf is None:
            path_to_scf = self.collect_commissioning_file(outputdir)

        param = "com.nokia.asi:HUBMOD_R"
        line_with_param = self.device.get_cmd(cmd_name="cat",
                                              cmd_params={"path": path_to_scf,
                                                          "options": "| grep " + param})

        lines = line_with_param(timeout=60)['LINES']
        id_list = [re.compile(r'ASI-\d+/ASI_R-\d+/HUBMOD_R-(\d+)"').findall(line)[0] for line in lines]

        asi_hw_list = []
        for i in id_list:
            single_hub_hwinfo = self.get_hub_hwinfo(path_to_scf, str(i))
            asi_hw_list.append(single_hub_hwinfo)
        return asi_hw_list

    @MolerTest.raise_background_exceptions()
    def get_hw_inventory_info(self):
        """
        Executes GetHwInventoryInfo on Asir Manager and parses output file into dictionary.

        :return: Dictionary with GetHwInventoryInfo file output.
        """
        try:
            hw_inventory_info = self.asirmg_cli_get_asi_hw_data()
        except Exception:
            logging.info("Get Asi hw list from CLI failed! try another way...")
            hub_inventory_info = {}
            hw_inventory_info = {}
            hw_info = self.get_asi_hw_data_based_on_commissioning()
            hub_inventory_info['HUBMOD_R'] = hw_info
            hw_inventory_info['HwInventoryInfo'] = hub_inventory_info
            logging.info("get_hw_inventory_info: asi hw info = %s" % hw_inventory_info)

        return hw_inventory_info

    @MolerTest.raise_background_exceptions()
    def get_antennas_number(self, number_of_hubs=1):
        """
        Check for number of antennas visible from Asir Manager.

        :return: number of antennas as int
        """
        hw_inventory_info = self.get_hw_inventory_info()
        visible_antennas_nr = 0

        for hub in range(0, number_of_hubs):
            one_hub_ants = len(hw_inventory_info['HwInventoryInfo']['HUBMOD_R'][hub]['ANTMOD_R'])
            visible_antennas_nr = visible_antennas_nr + one_hub_ants

        return visible_antennas_nr

    @MolerTest.raise_background_exceptions()
    def get_antennas_number_of_specific_hub(self, hub_id=1):
        """
        Check for number of antennas visible for specific HUB by hub_id from Asir Manager.

        :param hub_id:  int
        :return: number of antennas as int. None if no available hub id is found
        """
        hw_inventory_info = self.get_hw_inventory_info()
        hubs = hw_inventory_info['HwInventoryInfo']['HUBMOD_R']
        for hub in hubs:
            if hub_id == int(hub['@id']):
                return len(hub['ANTMOD_R'])
        return None

