    @MolerTest.raise_background_exceptions()
    def collect_commissioning_file(self, outputdir):
        """
        Collect SCF file from HUB and store it in outputdir

        :param outputdir: output directory for SCF file
        :return: path to SCF file
        """
        self.device.goto_state("CLI")
        get_scf = self.device.get_cmd(cmd_name="collectfiles",
                                      cmd_params={"ne": self.ne,
                                                  "pw": self.pw,
                                                  "outdir": outputdir,
                                                  "allfile": False,
                                                  "options": "-comm"})
        get_scf(timeout=150)

        return "{}/{}_scf.xml".format(outputdir, self.ne)

    @MolerTest.raise_background_exceptions()
    def collect_alarms_file(self, outputdir=None):
        """
        Collect xml file from HUB and store it in outputdir.

        :param outputdir: output directory for SCF file
        :return: path to SCF file
        """
        self.device.goto_state("CLI")
        cmd_collectfiles = self.device.get_cmd(
            cmd_name="collectfiles",
            cmd_params={"ne": self.ne, "allfile": False, "pw": self.pw, "outdir": outputdir, "options": "-alarm"})
        cmd_collectfiles(timeout=150)

        if outputdir:
            return "{}/alarms_{}.xml".format(outputdir, self.ne)
        else:
            return "alarms_{}.xml".format(self.ne)

    @MolerTest.raise_background_exceptions()
    def get_alarms_file_content(self, outputdir=None):
        """
        Get alarms as xml and convert it to dictionary.

        :param outputdir: directory where file is saved
        :return: alarms file content as dictionary
        """
        path_to_file = self.collect_alarms_file(outputdir)
        file_content = ''
        force_list_key = 'AlarmObservation'
        if outputdir is None:
            path_to_parse_file = '/opt/asir/' + path_to_file
        else:
            path_to_parse_file = path_to_file
        if os.path.exists(path_to_parse_file):
            with open(path_to_parse_file, 'r+') as f:
                file_content = f.read()
            if 'faultReport' in file_content:
                force_list_key = 'faultReport'
            elif 'AlarmObservation' in file_content:
                force_list_key = 'AlarmObservation'
            else:
                force_list_key = None
        return self.convert_xml_to_dict(path_to_parse_file, force_list=(force_list_key,))

    def _get_fault_report_alarms(self, content, alarm_list):
        """
        this method used to get alarm list with fault severity

        :return: No
        """
        for alarm in content['faultReport'][0]['fault']:
            if isinstance(alarm, string_types):
                sub_alarm = content['faultReport'][0]['fault']
                logging.info("Currently there is only one alarm on TL!")
                if sub_alarm['faultState'] == "active":
                    alarm_list.append(sub_alarm['faultId'])
                    break

            else:
                logging.info("Multiple alarms on TL now.")
                if alarm['faultState'] == 'active':
                    alarm_list.append(alarm['faultId'])

    @MolerTest.raise_background_exceptions()
    def get_alarms(self, path_to_file=None):
        """
        Get alarm numbers present on the ASiR Manager.

        :return: list of int or None
        """
        file_content = self.get_alarms_file_content(path_to_file)
        alarm_numbers_list = []
        if 'Alarms' in file_content and file_content['Alarms']:
            for alarm in file_content['Alarms']['AlarmObservation']:
                alarm_numbers_list.append(alarm['AlarmInformation']['AlarmText']['_alarmAdditionalInfo']
                                          ['additionalFaultId'])

        elif 'faultReport' in file_content and file_content['faultReport']:
            self._get_fault_report_alarms(file_content, alarm_numbers_list)

        else:
            alarm_numbers_list = None

        logging.info("ALARM LIST : {0}".format(alarm_numbers_list))

        return list(set(alarm_numbers_list))

    @MolerTest.raise_background_exceptions()
    def get_parameter_value_from_scf_file(self, path_to_scf_file, param):
        """
        Check if given parameter exists in SCF file specified in path_to_SCF_file and if it does return its value.

        :param path_to_scf_file: path to scf file
        :param param: name of the parameter
        :return: parameter value or None
        """
        line_with_param = self.device.get_cmd(cmd_name="cat", cmd_params={"path": path_to_scf_file,
                                                                          "options": "| grep " + param})
        line = line_with_param()
        MolerTest.info("Matched line {}".format(str(line['LINES'][0])))

        match = re.match(".*<p name=\"{}\">(?P<value>.*?)</p>.*".format(param), line['LINES'][0])
        if not match:
            return None
        else:
            return match.group('value')

    @MolerTest.raise_background_exceptions()
    def check_if_param_exist_in_scf_file(self, path_to_scf_file, param):
        """
        Check if parameter exist in SCF file

        :param path_to_scf_file: path to scf file
        :param param: name of the parameter
        :return: bool if param exist
        """
        return bool(self.get_parameter_value_from_scf_file(path_to_scf_file, param))

    @MolerTest.raise_background_exceptions()
    def change_parameter_in_scf_file(self, path_to_scf_file, param, value):
        """
        Change parameter in collected SCF file value.

        :param path_to_scf_file: path to scf file
        :param param: name of a parameter
        :param value: value to set
        :return: nothing
        """
        if self.check_if_param_exist_in_scf_file(path_to_scf_file, param):
            MolerTest.info("Changing commission file: {}".format(path_to_scf_file))
            change_file = self.device.get_cmd(
                cmd_name="sed",
                cmd_params={
                    'input_files': [path_to_scf_file],
                    'scripts': [r"s/<p name=\"{}\">[^/]*<\/p>/<p name=\"{}\">{}<\/p>/g".format(param, param, value)],
                    'options': "-E -i"
                })
            change_file()
        else:
            MolerTest.error("There is no such parameter as {}".format(param))

