    def get_ant_status(self, ant_id, ants=None):
        if ants is None:
            ants = self.get_all_ants_status()
        for i in ants['raml']['cmData']['managedObject']:
            if i['@distName'] == 'ASI-1/ASI_R-1/ANTMOD_R-{}'.format(ant_id):
                if '#text' in i['p'][2] and i['p'][2]['@name'] == 'hwState':
                    status = i['p'][2]['#text']
                elif '#text' in i['p'][1] and i['p'][1]['@name'] == 'hwState':
                    status = i['p'][1]['#text']
                else:
                    status = 'not working'

                return status == 'working'
        raise HardwareException('There is no ant with id {}'.format(ant_id))

    def get_all_ants_status(self):
        self.device.goto_state("CLI")
        reset_ant_cmd = self.device.get_cmd(cmd_name="get_states", cmd_params={"ne": self.ne,
                                                                               "pw": self.pw,
                                                                               "unit_type": "ant"})
        reset_ant_cmd(timeout=60)
        ants = self.convert_xml_to_dict('GetStates_{}.xml'.format(self.ne), force_list='managedObject')

        return ants

    @MolerTest.raise_background_exceptions()
    def reset_asirant(self, number_of_ant, output_dir='.'):
        """
        To reset asir ant via cli command.
        cli log will be saved into output_dir.

        :param number_of_ant: int, ant id
        :param output_dir: str, redirects all output files of cli cmd to a specific directory.
        """
        self.device.goto_state("CLI")
        reset_ant_cmd = self.device.get_cmd(cmd_name="resetunit",
                                            cmd_params={"ne": self.ne,
                                                        "pw": self.pw,
                                                        "unit_type": "ASIANT",
                                                        "number": number_of_ant,
                                                        "options": "-outdir {}".format(output_dir)})

        reset_ant_cmd(timeout=200)

