    @MolerTest.raise_background_exceptions()
    def get_hub_number(self):
        """
        Check for number of hubs visible from Asir Manager.

        :return: number of hubs as int
        """
        hw_inventory_info = self.get_hw_inventory_info()
        visible_hubs_nr = len(hw_inventory_info['HwInventoryInfo']['HUBMOD_R'])

        return visible_hubs_nr

    def get_hub_status(self, hub_id):
        """
        Check each hub status.

        :param hub_id: instance id
        :return: true if the hub is working status, and false otherwise
        """
        hubs = self.get_all_hubs_status()
        for hub_obj in hubs['raml']['cmData']['managedObject']:
            if hub_obj['@distName'] == 'ASI-1/ASI_R-1/HUBMOD_R-{}'.format(hub_id):
                if '#text' in hub_obj['p'][2] and hub_obj['p'][2]['@name'] == 'hwState':
                    status = hub_obj['p'][2]['#text']
                elif '#text' in hub_obj['p'][1] and hub_obj['p'][1]['@name'] == 'hwState':
                    status = hub_obj['p'][1]['#text']
                else:
                    status = 'not working'
                return status == 'working'
        raise HardwareException('There is no hub with id {}'.format(hub_id))

    def get_all_hubs_status(self):
        """
        Get all hubs status.

        :return: all hub objects include status
        """
        self.device.goto_state("CLI")
        getstates_hub_cmd = self.device.get_cmd(cmd_name="get_states", cmd_params={"ne": self.ne,
                                                                                   "pw": self.pw,
                                                                                   "unit_type": "hub"})
        getstates_hub_cmd(timeout=60)
        hubs = self.convert_xml_to_dict('GetStates_{}.xml'.format(self.ne), force_list='managedObject')
        return hubs
